import { expect, test } from 'bun:test';
import { chunkArray } from './src/utils/chunk';

test('chunkArray splits evenly', () => {
  expect(chunkArray([1, 2, 3, 4], 2)).toEqual([[1, 2], [3, 4]]);
});

test('chunkArray splits unevenly', () => {
  expect(chunkArray([1, 2, 3, 4, 5], 2)).toEqual([[1, 2], [3, 4], [5]]);
});

test('chunkArray handles empty array', () => {
  expect(chunkArray([], 2)).toEqual([]);
});

test('chunkArray rejects zero or negative size', () => {
  expect(() => chunkArray([1, 2], 0)).toThrow();
  expect(() => chunkArray([1, 2], -1)).toThrow();
});
